contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take an amount to send with play. Must model both cases: revert when wrong value, or state change when correct.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // Record observable before-values
        uint potBefore = c.pot();
        uint bankBeforeBalance = address(c).balance; // contract balance

        bool reverted;
        // call play and capture revert state
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint potAfter = c.pot();
        uint bankAfterBalance = address(c).balance;

        // The general rule:
        // - If call reverted then amount != TICKET_AMOUNT.
        // - If call did not revert and amount == TICKET_AMOUNT then either:
        //     a) pot increased by amount (no payout happened), i.e. potAfter == potBefore + amount; or
        //     b) a payout happened and potAfter == 0 and the contract balance decreased by exactly FEE_AMOUNT (bank fee transferred out), i.e. bankAfterBalance == bankBeforeBalance - FEE_AMOUNT.
        // Note: we observe only public getters and balances; FEE_AMOUNT and TICKET_AMOUNT are constants in C, but not accessible here, so we express relationships relative to amount and observed balances.

        // Compose the assert accordingly
        // If reverted -> amount != C.TICKET_AMOUNT. Since we cannot read C.TICKET_AMOUNT, we assert that if reverted then pot unchanged and contract balance unchanged (no state change on revert).
        // If not reverted -> amount must equal TICKET_AMOUNT, so amount > 0 and either pot increased by amount or pot became zero and contract balance decreased by 1 (FEE_AMOUNT).

        assert(
            // Reverted case: no state change
            (reverted && potAfter == potBefore && bankAfterBalance == bankBeforeBalance)
            ||
            // Non-reverted: must have caused an observable valid transition
            (!reverted && (
                // Case A: pot increased by amount
                (potAfter == potBefore + amount)
                // Case B: payout occurred: pot reset to 0 and contract balance decreased by exactly 1
                || (potAfter == 0 && bankBeforeBalance >= bankAfterBalance && (bankBeforeBalance - bankAfterBalance) == 1)
            ))
        );
    }

    // Accept incoming Ether for payouts
    receive() external payable {}
}

