        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint potAfter = c.pot();
        uint contractBalanceAfter = address(c).balance;

        // General rule:
        // - If the call reverted then no observable state change occurred on c (pot and balance unchanged).
        // - If the call did not revert then the contract's balance increased by exactly the sent amount,
        //   and the pot either increased by that amount or was reset to zero (payout case).
