            (amount == C(address(c)).TICKET_AMOUNT() && (
                // if not reverted then potAfter is either increased by amount or reset to 0
                (!reverted && (potAfter == potBefore + amount || potAfter == 0))
            ))
        );
    }

    // accept Ether when contract c sends payouts
    receive() external payable {}
