contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking the ticket amount as parameter and sending that much Ether
    function run(uint amount) public payable {
        // require we have enough balance in this test contract to forward amount
        require(address(this).balance >= amount);
        // record observables before the call
        address bank_before = c.bank();
        uint pot_before = c.pot();
        uint balance_before = address(c).balance;

        bool reverted;
        // perform the call that may revert
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observables after the call
        address bank_after = c.bank();
        uint pot_after = c.pot();
        uint balance_after = address(c).balance;

        // General invariant to assert:
        // If the call did not revert and the sent amount equals the ticket price (10), then
        // 1) the bank address must remain unchanged, and
        // 2) ether is conserved: (pot_after + balance_after) == (pot_before + balance_before + amount)
        // If the call reverted or amount != 10, we don't constrain state (reverted may be true).
        assert(
            reverted || (amount != 10) || (
                bank_after == bank_before
                && (pot_after + balance_after) == (pot_before + balance_before + amount)
            )
        );
    }

    // receive to accept Ether when play pays out to this contract (though in C it pays to bank or msg.sender)
    receive() external payable {}
}

