    function run(uint sendAmount) public payable {
        require(address(this).balance >= sendAmount);

        // snapshot before-call observable state
        uint pot_before = c.pot();
        uint bal_before = address(c).balance;

        bool reverted;
        // perform the call sending Ether as requested
        try c.play{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint pot_after = c.pot();
        uint bal_after = address(c).balance;
        address bankAddr = c.bank();

        // The general invariant we assert:
        // - If the call reverted, nothing changed (pot and balance unchanged).
        // - Otherwise, the net change in (pot + contract balance) equals sendAmount minus at most 1 (the FEE_AMOUNT) which can be moved to bank during a payout.
        // We cannot reference the bank's balance directly, but we know at most FEE_AMOUNT (1) can leave the contract when a payout occurs.
        assert(
            (reverted && pot_after == pot_before && bal_after == bal_before)
            || (!reverted && (pot_after + bal_after) + 1 >= pot_before + bal_before + sendAmount && (pot_after + bal_after) <= pot_before + bal_before + sendAmount)
        );
    }

    // allow receiving refunds when c.transfer is invoked to this test contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint sendAmount) public payable {
        // we need Ether available to forward to c when requested
        require(address(this).balance >= sendAmount);

        // observe before state
        uint pot_before = c.pot();
        uint bal_before = address(c).balance;
        address bankAddr_before = c.bank();

        bool reverted;
        // call play forwarding sendAmount
        try c.play{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after state
        uint pot_after = c.pot();
        uint bal_after = address(c).balance;
        address bankAddr_after = c.bank();

        // General rule to assert (single assert):
        // If the call reverted, nothing observable about pot or balance changed.
        // Otherwise, when called with exactly the ticket amount (sendAmount == 10),
        // either:
        //  - No payout happened: pot increased by TICKET_AMOUNT and contract balance increased by TICKET_AMOUNT,
        //    so pot_after == pot_before + sendAmount && bal_after == bal_before + sendAmount
        //  - A payout happened: pot becomes 0 and contract balance decreased by pot_before (the full previous pot was paid out from contract),
        //    i.e., pot_after == 0 && bal_after + pot_before + 0 == bal_before + sendAmount - 1 || bal_after + pot_before == bal_before + sendAmount - 1
        // Also bank address never changes.

        assert(
            (reverted && pot_after == pot_before && bal_after == bal_before && bankAddr_after == bankAddr_before)
            || (!reverted && sendAmount == 10 && bankAddr_after == bankAddr_before && (
                (pot_after == pot_before + sendAmount && bal_after == bal_before + sendAmount)
                || (pot_after == 0 && (bal_before + sendAmount == bal_after + pot_before + 1))
            ))
        );
    }

    // allow receiving refunds/payments
    receive() external payable {}
}
